text.consumer:
private fun ktlspConsumerSlice(provider: ProblemSummaryData): String {
  return provider.ktlspSliceText().substring(0)
}

counter.consumer:
private fun ktlspConsumerSlice(provider: ProblemSummaryData): Int {
  return provider.ktlspSliceCounter().incrementAndGet()
}

